W += [
E('multitask','英 /ˌmʌltiˈtɑːsk/；美 /ˈmʌltiˌtæsk/','同时处理多项任务','手头不只一件事，需要在几项工作之间安排或切换。','现代可拆 multi- + task；计算机名词 multitasking 的记录早于常用动词 multitask，动词可看作从这一用法逆构。不能只因 -ing 像词尾，就断言先有动词。',M+[['英语 multi- + tasking → multitasking；后有动词 multitask','多任务执行 → 同时处理几件事']],'人在工作中 multitask 常包含注意力切换；计算机 multitask 可以通过调度让多个任务并发推进。词本身不承诺每项任务都在同一瞬间执行。','learn to multitask；multitask effectively；a computer can multitask。','multitask 说任务处理方式；multithread 涉及程序线程结构，不是同义词。',('I find it harder to multitask when the work is unfamiliar.','工作不熟悉时，我更难同时兼顾多项任务。'),('The system can multitask while a large file is downloading.','下载大文件时，系统仍能同时处理其他任务。'),sources=['https://www.etymonline.com/word/multitasking','https://www.merriam-webster.com/dictionary/multitask']),
E('multitasking','英 /ˌmʌltiˈtɑːskɪŋ/；美 /ˈmʌltiˌtæskɪŋ/','多任务处理；同时兼顾多件事','把几项工作放在同一段时间里推进，而不是先彻底做完一件再开始下一件。','早期计算机术语 multi- + tasking；后来广用于人的工作安排。现代虽可看成 multitask + -ing，历史名词用法更早。',M+[['英语 multi- + tasking → multitasking','先用于计算机并发执行，后用于人的多项活动']],'multitasking can mean switching between tasks：在人类活动中，常体现为来回切换。这个词只描述处理多项任务，不等于效率一定更高。','multitasking ability；support multitasking；the demands of multitasking。','parallel processing 强调某些工作真正同时执行；multitasking 可以靠轮流分配时间实现。',('The new operating system improved multitasking.','新操作系统改进了多任务处理能力。'),('She reduced multitasking by checking messages at set times.','她通过定时查看消息，减少了来回兼顾多项任务。'),sources=['https://www.etymonline.com/word/multitasking','https://www.merriam-webster.com/dictionary/multitasking']),
E('multifunction','/ˌmʌltiˈfʌŋkʃən/','多功能的','一台设备装下几种功能，不只完成一种工作。','multi- + function“功能”；作形容词时 function 不需要变成复数。',M+[['英语 multi- + function → multifunction','能执行多项功能的']],'a multifunction printer 可打印、扫描等；a multifunction button 根据操作方式承担不同功能。名称只说明功能不止一个，具体功能须看说明。','a multifunction printer；a multifunction device；a multifunction button。','multipurpose 强调用途，multifunction 强调实际功能模块；二者常有交集。',('The office replaced two machines with one multifunction printer.','办公室用一台多功能打印机替换了两台机器。'),('The watch has a multifunction button on the side.','手表侧面有一个多功能按钮。'),sources=['https://www.merriam-webster.com/dictionary/multifunction','https://en.wiktionary.org/wiki/multifunction#English']),
E('multifunctional','/ˌmʌltiˈfʌŋkʃənəl/','多功能的','一个空间、物件或部件可以发挥好几种作用。','multi- + functional“有某种功能的”；也可与 multifunction 联系理解，但不必认定每次都是后者加 -al。',M+[['英语 multi- + functional → multifunctional','具有多种功能的']],'multifunctional furniture 可收纳、坐卧等；a multifunctional space 可适应不同活动。比单独说 useful 更具体地强调功能种类。','multifunctional furniture；a multifunctional space；multifunctional equipment。','functional 常说能正常发挥作用或偏实用；multifunctional 再增加多种功能这一层意思。',('The small flat uses multifunctional furniture to save space.','这套小公寓用多功能家具节省空间。'),('The lobby was designed as a multifunctional space.','大厅被设计成一个多功能空间。'),sources=['https://www.merriam-webster.com/dictionary/multifunction','https://en.wiktionary.org/wiki/multifunctional#English']),
E('multivitamin','英 /ˌmʌltiˈvɪtəmɪn/；美 /ˌmʌltiˈvaɪtəmɪn/','复合维生素制剂；含多种维生素的','一份产品里配入多种维生素，而不是单独一种。','multi- + vitamin；名词是这类制剂，形容词常放在 tablet、supplement 前。',M+[['英语 multi- + vitamin → multivitamin','含多种维生素的；这类制剂']],'a multivitamin tablet 是复合维生素片；产品也可能含矿物质。multi- 只说明有多种，不表示各种维生素都齐全、剂量相同或适合每个人。','a multivitamin tablet；a multivitamin supplement；a multivitamin formula。','vitamin C 是特定维生素；a multivitamin 是含多种维生素的制剂，两者不是同一层级名称。',('The label lists the ingredients in the multivitamin.','标签列出了这款复合维生素的成分。'),('The study compared several multivitamin formulations.','这项研究比较了几种复合维生素配方。'),sources=['https://www.collinsdictionary.com/dictionary/english/multivitamin','https://en.wiktionary.org/wiki/multivitamin#English']),
E('multibillion','/ˌmʌltiˈbɪljən/','数十亿的；涉及多个十亿单位的','数额不是一两个百万，而是以好几个十亿来算。','multi- + billion；现代英语 billion 通常为十亿，multi- 说明多个这样的单位。',M+[['英语 multi- + billion → multibillion','多个十亿单位的规模']],'a multibillion enterprise 可指价值或规模达数十亿货币单位的企业；实际是哪种币种要看上下文。新闻也常用带连字符的更长复合修饰语。','a multibillion business；a multibillion industry；multibillion investment。','million 是百万，billion 是十亿；不能把 multibillion 误译成数百万。',('The company grew into a multibillion business.','这家公司发展成了一家规模达数十亿的企业。'),('The report examines a multibillion industry.','报告考察了一个规模达数十亿的行业。'),sources=['https://en.wiktionary.org/wiki/multibillion#English']),
E('multimillionaire','英 /ˌmʌltimɪljəˈneə/；美 /ˌmʌltimɪljəˈner/','拥有数百万资产的人；大富翁','财富超过一个百万单位，达到好几个百万。','multi- + millionaire“百万富翁”；millionaire 经法语来源进入英语后，再与 multi- 结合。',M+[['英语 multi- + millionaire → multimillionaire','拥有多个百万单位财富的人']],'a multimillionaire 的财富单位由语境决定；它常说净资产，不必全是银行里的现金。不能直接按中文习惯一概换算成人民币。','become a multimillionaire；a self-made multimillionaire〔短语〕；a multimillionaire investor。','millionaire 达到百万级；multimillionaire 强调数百万或更多，billionaire 则到十亿级。',('Selling the company made her a multimillionaire.','出售公司使她成为拥有数百万资产的富翁。'),('The multimillionaire donated part of his collection to the museum.','这位大富翁把部分藏品捐给了博物馆。'),sources=['https://en.wiktionary.org/wiki/multimillionaire#English']),
E('multicellular','英 /ˌmʌltiˈseljʊlə/；美 /ˌmʌltiˈseljələr/','多细胞的','一个生物体由许多细胞一起组成，而不是只有一个细胞。','multi- + cellular“细胞的”，cellular 接 cell；是现代生物学构词，multi- 本身不说明细胞分工有多复杂。',M+[['英语 multi- + cellular → multicellular','由多个细胞组成的']],'plants and animals are multicellular 是说植物、动物由多个细胞组成；一个多细胞生物里的细胞可以承担不同任务。词义说组成，不是体积一定很大。','a multicellular organism；multicellular life；multicellular structure。','unicellular 是单细胞；multicellular 是多细胞。微小不必等于单细胞。',('A tree is a multicellular organism.','树是一种多细胞生物。'),('The lesson compares unicellular and multicellular life.','这节课比较单细胞与多细胞生命。'),sources=['https://en.wiktionary.org/wiki/multicellular#English']),
E('multilayer','英 /ˌmʌltiˈleɪə/；美 /ˌmʌltiˈleɪər/','多层的','像叠好的薄片，一层上面还有别的层。','multi- + layer“层”；常在名词前说明材料或结构由多层组成。',M+[['英语 multi- + layer → multilayer','含有多层结构的']],'multilayer packaging 是多层包装；a multilayer coating 是多层涂层。每层可以承担不同任务，不代表每层材质一样。','multilayer packaging；a multilayer coating；a multilayer structure。','multilevel 常说层级或楼层；multilayer 更容易让人想到材料叠层，但抽象结构中也可使用。',('The package uses a multilayer film.','包装使用了多层薄膜。'),('The diagram shows the multilayer structure of the panel.','图示展示了这块板材的多层结构。'),sources=['https://en.wiktionary.org/wiki/multilayer#English']),
E('multilayered','英 /ˌmʌltiˈleɪəd/；美 /ˌmʌltiˈleɪərd/','有多层的；多层次的','既能指材料层层叠起，也能指故事一层之下还有另一层意思。','multi- + layered“分层的、有层次的”；现代可同时联系 multilayer，不必把两者看成不同词根。',M+[['英语 multi- + layered → multilayered','有多个物理或意义层次的']],'a multilayered fabric 是多层织物；a multilayered character 是不止一种简单性格的人物。比喻用法强调值得逐层理解。','a multilayered story；a multilayered character；a multilayered structure。','complicated 只说复杂；multilayered 更具体地暗示多层意义或结构，不一定难以理解。',('The novel presents a multilayered portrait of family life.','小说从多个层次描绘了家庭生活。'),('The jacket has a multilayered lining.','这件夹克有多层衬里。'),sources=['https://en.wiktionary.org/wiki/multilayered#English']),
E('multiparty','英 /ˌmʌltiˈpɑːti/；美 /ˌmʌltiˈpɑːrti/','多党派的；多方参与的','桌边有多个党派或参与方，不只一个组织独自决定。','multi- + party；这里 party 可以是政党，也可以是协议、诉讼或交谈的一方。',M+[['英语 multi- + party → multiparty','多个党派或参与方共同涉及的']],'a multiparty system 是多党制；multiparty negotiations 是多方谈判，不一定都是政党。不要把所有 party 都理解成聚会。','a multiparty system；multiparty elections；multiparty negotiations。','multilateral 常说多边关系；multiparty 直接强调多个参与方，法律、商业场景也常见。',('The country introduced a multiparty electoral system.','这个国家引入了多党参与的选举制度。'),('The dispute led to lengthy multiparty negotiations.','这场争议引发了漫长的多方谈判。'),sources=['https://en.wiktionary.org/wiki/multiparty#English']),
E('multiyear','英 /ˌmʌltiˈjɪə/；美 /ˌmʌltiˈjɪr/','持续多年的；跨多年的','安排不只覆盖今年，而是延伸好几个年头。','multi- + year；作前置修饰语时 year 保持单数形式。',M+[['英语 multi- + year → multiyear','时间跨度超过一年的']],'a multiyear contract 是多年合同；a multiyear study 是跨年研究。它不说明恰好几年，也不等于每年重复一次。','a multiyear contract；a multiyear plan；a multiyear study。','annual 是每年一次或年度的；multiyear 是一次安排跨多年。多年项目可以每年提交年度报告。',('The museum began a multiyear restoration project.','博物馆启动了一个持续多年的修复项目。'),('They signed a multiyear supply agreement.','他们签订了多年供货协议。'),sources=['https://en.wiktionary.org/wiki/multiyear#English']),
E('multistage','/ˌmʌltiˈsteɪdʒ/','多阶段的；多级的','事情分成几段逐步进行，不是一次就全部完成。','multi- + stage“阶段、级”；火箭、处理流程、选拔等语境各有具体的阶段。',M+[['英语 multi- + stage → multistage','由多个先后阶段或级构成的']],'a multistage process 有多个处理步骤；a multistage selection procedure 是分几轮筛选。它强调阶段结构，不表示过程一定缓慢。','a multistage process；multistage selection；a multistage rocket。','multilevel 重层级，multistage 重阶段。审批可以多级，也可以多阶段，两种结构有时同时存在。',('The application goes through a multistage review process.','申请要经过多阶段审查。'),('The experiment uses a multistage filtration system.','实验使用多级过滤系统。'),sources=['https://en.wiktionary.org/wiki/multistage#English']),
E('multimeter','英 /ˈmʌltiˌmiːtə/；美 /ˈmʌltiˌmiːtər/，也读 /ˌmʌlˈtɪmətər/','万用表','同一台表能测几种电学量，所以叫“多种测量的仪表”。','multi- + -meter“测量仪”；-meter 接希腊 métron“尺度、测量”。这里不是 multi + metre“多米长”。',M+[['英语 multi- + -meter → multimeter','具有多种电学测量功能的仪表']],'a digital multimeter 是数字万用表，通常可测电压、电流、电阻等；具体功能取决于型号。词源中的“多”不是说它能测所有物理量。','a digital multimeter；a multimeter reading；use a multimeter。','voltmeter 专测电压；multimeter 合并多种测量功能。两者不是大小不同的同类名称。',('The technician checked the battery voltage with a multimeter.','技术人员用万用表检查了电池电压。'),('The multimeter displayed a steady reading.','万用表显示了一个稳定的读数。'),sources=['https://www.merriam-webster.com/dictionary/multimeter','https://en.wiktionary.org/wiki/multimeter#English']),
E('multigenerational','/ˌmʌltiˌdʒenəˈreɪʃənəl/','多代人的；跨几代的','祖辈、父辈和晚辈等几代人一起出现在同一生活或故事里。','multi- + generational“代际的”；generation 在这里是人的一代，不是机器发电。',M+[['英语 multi- + generational → multigenerational','涉及多个人类世代的']],'a multigenerational household 是多代同住家庭；a multigenerational novel 可以追踪几代人的故事。它不要求每个人都生活在同一年。','a multigenerational household；multigenerational living；a multigenerational story。','intergenerational 强调代与代之间的联系；multigenerational 强调涉及多代，两者可重叠。',('The house was designed for multigenerational living.','这栋房子按多代人共同居住的需要设计。'),('The novel follows a multigenerational family history.','小说讲述了一个家庭跨越几代人的历史。'),sources=['https://en.wiktionary.org/wiki/multigenerational#English']),
E('multiplexer','英 /ˈmʌltɪpleksə/；美 /ˈmʌltɪpleksər/','多路复用器；多路选择器','几条输入要共用一个出口，由这个装置安排或选择。','multiplex + -er；-er 表执行多路复用功能的装置，不是电影院工作人员。',L+[['英语 multiplex → multiplex + -er → multiplexer','多路复用 → 执行复用或选择的装置']],'数字电路中的 multiplexer 可以根据选择信号从多路输入选一路输出；通信设备中的用法也可指把多路信号组合到共享传输资源的装置。具体工作方式看系统。','a digital multiplexer；a multiplexer input；an eight-input multiplexer。','demultiplexer 常做相反方向的分配或分离；multiplexer 不是简单把所有输入电压相加。',('The multiplexer selects one of the input signals.','多路选择器从输入信号中选出一路。'),('The circuit uses a multiplexer to share the output line.','电路使用多路选择器共用输出线路。'),sources=['https://www.merriam-webster.com/dictionary/multiplexer','https://www.ti.com/product/SN74HC151']),
E('multicore','英 /ˌmʌltiˈkɔː/；美 /ˌmʌltiˈkɔːr/','多核的','一颗处理器里有多个可以执行计算工作的核心。','multi- + core“核心”；现代计算机用法由物体中心、核心的比喻发展而来。',M+[['英语 multi- + core → multicore','包含多个核心，尤指处理器核心']],'a multicore processor 可以让合适的任务利用多个核心；有多个核心不意味着每个程序自动按核心数等比例变快。也要看任务是否能分开。','a multicore processor；multicore performance；multicore architecture。','multithreading 说线程组织或执行；multicore 说硬件核心数。多线程程序可以在单核上通过切换运行。',('The software was updated to use multicore processors more effectively.','软件更新后能更有效地利用多核处理器。'),('This task gains little from multicore hardware.','这个任务从多核硬件中获得的收益不大。'),sources=['https://en.wiktionary.org/wiki/multicore#English','https://learn.microsoft.com/en-us/windows/win32/procthread/processes-and-threads']),
E('multithreading','/ˌmʌltiˈθredɪŋ/','多线程处理','一个进程里安排多条执行线索，使不同工作可以交错或同时推进。','multi- + threading；thread 原是线，计算机借它表示一条执行线索。不是多根物理电线。',M+[['英语 multi- + threading → multithreading','多个执行线程参与工作']],'multithreading 可让一个线程处理界面、另一个等待数据；在合适硬件与调度下也可并行执行。它需要协调共享数据，线程多本身不保证更快。','support multithreading；use multithreading；multithreading issues。','multiprocessing 常涉及多个进程；multithreading 强调多个线程，线程通常共享所属进程的资源。',('The application uses multithreading to keep the interface responsive.','应用使用多线程，让界面保持响应。'),('The bug appeared only after multithreading was enabled.','这个错误只在启用多线程后才出现。'),sources=['https://en.wiktionary.org/wiki/multithreading#English','https://learn.microsoft.com/en-us/windows/win32/procthread/processes-and-threads']),
E('multiprocessor','英 /ˌmʌltiˈprəʊsesə/；美 /ˌmʌltiˈprɑːsesər/','多处理器的；多处理器系统','让多个处理单元共同参与计算，而不只依赖一个。','multi- + processor“处理器”；processor 来自 process + -or，整个词是现代计算机复合词。',M+[['英语 multi- + processor → multiprocessor','含多个处理器的系统或结构']],'a multiprocessor system 是多处理器系统；具体文献对处理器、核心的划分可能不同，读架构说明时要看它的定义。不是只开了几个软件窗口就叫多处理器。','a multiprocessor system；multiprocessor architecture；a multiprocessor machine。','multicore 强调一颗芯片内多个核心；multiprocessor 强调系统中多个处理器，较广的讨论中两者可能有交集。',('The operating system supports multiprocessor systems.','这个操作系统支持多处理器系统。'),('The team tested the workload on a multiprocessor machine.','团队在一台多处理器机器上测试了这项工作负载。'),sources=['https://en.wiktionary.org/wiki/multiprocessor#English']),
E('multipolar','英 /ˌmʌltiˈpəʊlə/；美 /ˌmʌltiˈpoʊlər/','多极的；有多个力量中心的','不是只有一个中心发号施令，也不是只剩两边对峙。','multi- + polar“极的”；pole 从端点、磁极等用法扩展到力量中心。',M+[['英语 multi- + polar → multipolar','有多个极或力量中心的']],'a multipolar world 常说多个大国或地区中心具有影响力的国际格局；物理等领域则有实际的多极结构。政治用法描述力量分布，不保证各方完全平等。','a multipolar world；a multipolar order；a multipolar system。','bipolar 是两极，unipolar 是单极；multilateral 说多方参与，multipolar 说力量中心的分布。',('The essay discusses the possibility of a multipolar world.','文章讨论了多极世界的可能性。'),('A multipolar order can involve several centres of influence.','多极格局可以包含多个影响力中心。'),sources=['https://en.wiktionary.org/wiki/multipolar#English'])
]
m=json.loads((BASE/'.cache/batch200/rewrite_spec.json').read_text());family=next(r['family'] for r in m['roots'] if r['id']=='C0771')
